SELECT 'weapons' AS what, COUNT(*) AS n FROM item_template WHERE entry IN (90120,90121,90122,90123,90124,90125,90126,90127,90128,90129,90130,90131,90132,90133,90134);
SELECT 'recipes' AS what, COUNT(*) AS n FROM skill_line_ability WHERE spell_id IN (38300,38301,38302,38303,38304,38305,38306,38307,38308,38309,38310,38311,38312,38313,38314);
SELECT it.name, it.item_level AS ilvl, it.dmg_min1 AS dmin, it.dmg_max1 AS dmax, sla.req_skill_value AS skill
FROM item_template it JOIN spell_template s ON s.effectItemType1=it.entry
JOIN skill_line_ability sla ON sla.spell_id=s.entry
WHERE it.entry IN (90120,90121,90122,90123,90124,90125,90126,90127,90128,90129,90130,90131,90132,90133,90134) ORDER BY it.item_level;
